import{_ as t,c as a,o as r,ag as n}from"./chunks/framework.ARG558ZT.js";const u=JSON.parse('{"title":"What is WCAG standard? What parts it contains? Web Content Accessibility Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/A11y/What_is_WCAG_standard__What_parts_it_contains_Web_Content_Accessibility_Guidelines.md","filePath":"senior_growth/A11y/What_is_WCAG_standard__What_parts_it_contains_Web_Content_Accessibility_Guidelines.md"}'),i={name:"senior_growth/A11y/What_is_WCAG_standard__What_parts_it_contains_Web_Content_Accessibility_Guidelines.md"};function s(o,e,d,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="what-is-wcag-standard-what-parts-it-contains-web-content-accessibility-guidelines" tabindex="-1">What is WCAG standard? What parts it contains? Web Content Accessibility Guidelines <a class="header-anchor" href="#what-is-wcag-standard-what-parts-it-contains-web-content-accessibility-guidelines" aria-label="Permalink to “What is WCAG standard? What parts it contains? Web Content Accessibility Guidelines”">​</a></h1><h2 id="🔹-wcag-web-content-accessibility-guidelines" tabindex="-1">🔹 WCAG: Web Content Accessibility Guidelines <a class="header-anchor" href="#🔹-wcag-web-content-accessibility-guidelines" aria-label="Permalink to “🔹 WCAG: Web Content Accessibility Guidelines”">​</a></h2><p><strong>WCAG</strong> (Web Content Accessibility Guidelines) is a set of <strong>international standards</strong> that define how to make web content <strong>accessible to people with disabilities</strong>. It is maintained by the <strong>W3C Web Accessibility Initiative (WAI)</strong>.</p><hr><h2 id="_1️⃣-purpose-of-wcag" tabindex="-1">1️⃣ Purpose of WCAG <a class="header-anchor" href="#_1️⃣-purpose-of-wcag" aria-label="Permalink to “1️⃣ Purpose of WCAG”">​</a></h2><ul><li><p>Provides <strong>guidelines and success criteria</strong> for making web content:</p><ul><li><strong>Perceivable</strong> – users can see or hear content.</li><li><strong>Operable</strong> – users can interact with content.</li><li><strong>Understandable</strong> – users can understand the content and interface.</li><li><strong>Robust</strong> – content works across devices and assistive technologies.</li></ul></li><li><p>Supplies a technical accessibility baseline; applicable contractual/legal scope and version are separate from this study lesson.</p></li></ul><hr><h2 id="_2️⃣-structure-of-wcag" tabindex="-1">2️⃣ Structure of WCAG <a class="header-anchor" href="#_2️⃣-structure-of-wcag" aria-label="Permalink to “2️⃣ Structure of WCAG”">​</a></h2><p>WCAG is organized into <strong>4 principles (POUR)</strong>, <strong>guidelines</strong>, and <strong>success criteria</strong>.</p><table tabindex="0"><thead><tr><th>Principle</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Perceivable</strong></td><td>Users must be able to <strong>perceive content</strong> with at least one sense. (Text alternatives, captions, adaptable layouts)</td></tr><tr><td><strong>Operable</strong></td><td>Users must be able to <strong>interact with the interface</strong>. (Keyboard navigation, enough time, clear focus)</td></tr><tr><td><strong>Understandable</strong></td><td>Users must be able to <strong>comprehend information and UI</strong>. (Readable text, predictable navigation, error suggestions)</td></tr><tr><td><strong>Robust</strong></td><td>Content must be <strong>compatible with current and future assistive technologies</strong>. (Proper HTML, ARIA, standard APIs)</td></tr></tbody></table><hr><h2 id="_3️⃣-wcag-versions-levels" tabindex="-1">3️⃣ WCAG Versions &amp; Levels <a class="header-anchor" href="#_3️⃣-wcag-versions-levels" aria-label="Permalink to “3️⃣ WCAG Versions &amp; Levels”">​</a></h2><h3 id="_3-1-versions" tabindex="-1">3.1 Versions <a class="header-anchor" href="#_3-1-versions" aria-label="Permalink to “3.1 Versions”">​</a></h3><ul><li><strong>WCAG 2.0</strong> (2008) – widely adopted, stable</li><li><strong>WCAG 2.1</strong> (2018) – added mobile, low vision, and cognitive accessibility criteria</li><li><strong>WCAG 2.2</strong> is a W3C Recommendation; the linked published Recommendation is dated12December2024. It adds criteria addressing focus, dragging, target size, redundant entry and accessible authentication.</li></ul><h3 id="_3-2-conformance-levels" tabindex="-1">3.2 Conformance Levels <a class="header-anchor" href="#_3-2-conformance-levels" aria-label="Permalink to “3.2 Conformance Levels”">​</a></h3><table tabindex="0"><thead><tr><th>Level</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>Minimum accessibility; basic issues fixed</td></tr><tr><td><strong>AA</strong></td><td>All applicable A and AA criteria in the declared scope; not an issue-severity category</td></tr><tr><td><strong>AAA</strong></td><td>Highest level; very strict, often impractical for all content</td></tr></tbody></table><blockquote><p>This learning path targets WCAG2.2AA material. Legal/contract obligations can refer to different versions and require a separate applicable assessment; a tool score does not establish legal compliance.</p></blockquote><hr><h2 id="_4️⃣-examples-of-success-criteria" tabindex="-1">4️⃣ Examples of Success Criteria <a class="header-anchor" href="#_4️⃣-examples-of-success-criteria" aria-label="Permalink to “4️⃣ Examples of Success Criteria”">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>Example Criterion</th></tr></thead><tbody><tr><td>Perceivable</td><td>Provide text alternatives for images (<code>alt</code> text).</td></tr><tr><td>Operable</td><td>All functionality accessible via keyboard.</td></tr><tr><td>Understandable</td><td>Instructions and error messages are clear and understandable.</td></tr><tr><td>Robust</td><td>Proper semantic HTML and ARIA usage for assistive technologies.</td></tr></tbody></table><hr><h2 id="_5️⃣-tools-for-wcag-testing" tabindex="-1">5️⃣ Tools for WCAG Testing <a class="header-anchor" href="#_5️⃣-tools-for-wcag-testing" aria-label="Permalink to “5️⃣ Tools for WCAG Testing”">​</a></h2><ul><li><strong>Automated:</strong> Lighthouse, axe DevTools, WAVE, Pa11y</li><li><strong>Manual:</strong> Keyboard navigation, screen readers, color contrast checkers</li></ul><hr><h3 id="✅-summary" tabindex="-1">✅ Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “✅ Summary”">​</a></h3><ul><li><strong>WCAG</strong> = international standard for web accessibility.</li><li>Organized by <strong>4 principles (POUR)</strong>: Perceivable, Operable, Understandable, Robust.</li><li>Contains <strong>guidelines and success criteria</strong> with 3 conformance levels (A, AA, AAA).</li><li>Provides testable criteria; meeting them does not address every user need or establish every legal obligation.</li></ul><blockquote><p>💡 Senior Tip:<br> Use <strong>WCAG2.2AA</strong> as this study baseline, and state the actual assessment scope and supported technologies. Choose semantic HTML and necessary ARIA, then assess every applicable criterion and conformance requirement in the declared scope.</p></blockquote><h2 id="criteria-mapped-to-implementation-decisions" tabindex="-1">Criteria mapped to implementation decisions <a class="header-anchor" href="#criteria-mapped-to-implementation-decisions" aria-label="Permalink to “Criteria mapped to implementation decisions”">​</a></h2><table tabindex="0"><thead><tr><th>Criterion / level</th><th>Concrete design and verification</th></tr></thead><tbody><tr><td>1.1.1 A</td><td>Meaningful text alternatives; decorative images use empty alt</td></tr><tr><td>1.3.1 A</td><td>Labels, headings, fieldsets/legends, table header relationships</td></tr><tr><td>1.4.3 AA</td><td>Text contrast at least4.5:1; qualifying large text3:1; check stated exceptions</td></tr><tr><td>1.4.10 AA</td><td>Reflow at320CSS-px width without two-dimensional scrolling except permitted content such as data tables</td></tr><tr><td>1.4.11 AA</td><td>Necessary control/state and meaningful graphic contrast3:1, subject to criterion exceptions</td></tr><tr><td>2.1.1 A / 2.1.2 A</td><td>Keyboard operation and no keyboard trap; modal containment has an operable exit</td></tr><tr><td>2.4.3 A / 2.4.7 AA</td><td>Logical focus order and visible focus</td></tr><tr><td>2.4.11 AA (new2.2)</td><td>Focused component not entirely hidden by author-created content, e.g. sticky banner</td></tr><tr><td>2.5.7 AA (new2.2)</td><td>Dragging has a single-pointer alternative unless an exception applies</td></tr><tr><td>2.5.8 AA (new2.2)</td><td>Pointer targets meet24×24CSS-px size or the defined spacing/other exceptions</td></tr><tr><td>3.3.1 A / 3.3.2 A / 3.3.3 AA</td><td>Identify errors, provide labels/instructions and useful correction suggestions</td></tr><tr><td>3.3.7 A (new2.2)</td><td>Avoid requiring repeated information within a process unless an exception applies</td></tr><tr><td>3.3.8 AA (new2.2)</td><td>Authentication does not require a cognitive-function test without a permitted alternative/mechanism; support password managers and paste</td></tr><tr><td>4.1.2 A / 4.1.3 AA</td><td>Expose names/roles/states; announce appropriate status changes without moving focus</td></tr></tbody></table><p>AAA Focus Appearance2.4.13 is distinct from AA Focus Visible2.4.7; a project can adopt stronger focus styling without mislabelling levels. WCAG2.2 removes4.1.1Parsing, but invalid markup can still break relationships and other criteria. Consult each criterion&#39;s exact wording and exceptions rather than reducing conformance to this table.</p><p><strong>Worked decision:</strong> a draggable priority list gains Move up/Move down buttons with clear item names. The buttons provide the nondrag pointer path (2.5.7), also support keyboard operation (2.1.1), preserve focus on the moved item and announce the new position (4.1.3). A screen-reader and pointer test must confirm the result; adding button markup alone is insufficient.</p><p>Official normative source: <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noreferrer">WCAG2.2</a>; explanatory guidance: <a href="https://www.w3.org/WAI/WCAG22/Understanding/" target="_blank" rel="noreferrer">Understanding WCAG2.2</a>. Checked2026-10-20.</p><h2 id="criterion-specific-visual-input-regression-plan" tabindex="-1">Criterion-specific visual/input regression plan <a class="header-anchor" href="#criterion-specific-visual-input-regression-plan" aria-label="Permalink to “Criterion-specific visual/input regression plan”">​</a></h2><p>Conformance considers complete pages/processes at the claimed level, accessibility-supported technologies and other requirements; a selected component checklist is not a complete claim. Document the product scope, relevant exclusions/alternatives and actual evidence. A/AA/AAA describe cumulative criterion levels, not “minor/major/critical bug” labels. Keep defects by user impact independently.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Procedure and design reasoning</th><th>Criterion connection / boundary</th></tr></thead><tbody><tr><td>Text enlargement</td><td>Enlarge text up to200%, including labels/errors/buttons; inspect clipping, overlap and hidden actions</td><td>1.4.4AA; don&#39;t disable zoom or assume rem guarantees success</td></tr><tr><td>Reflow</td><td>Test vertical content at320CSS-px equivalent (e.g.1280wide at400% zoom); preserve information/functions without two-direction scrolling</td><td>1.4.10AA; permitted two-dimensional content exceptions are local, not a waiver for surrounding controls/cells</td></tr><tr><td>Text spacing</td><td>Apply line height1.5×, paragraph spacing2× font size, letter spacing.12× and word spacing.16× without loss</td><td>1.4.12AA; these are override tolerances, not mandatory default typography</td></tr><tr><td>Text/UI contrast</td><td>Measure actual foreground/background including transparency, gradients, themes, states and focus context</td><td>1.4.3AA text4.5:1 / qualifying large text3:1;1.4.11AA necessary non-text3:1 with exact exceptions</td></tr><tr><td>Focus/obscuration</td><td>Keyboard every action under sticky headers/banners, opened panels and zoom; inspect visible focus and order</td><td>2.4.3A,2.4.7AA,2.4.11AA; AAA focus appearance2.4.13 has additional specifics</td></tr><tr><td>Motion</td><td>Change reduced-motion preference during an animation, verify static meaning and pause/stop for relevant automatic motion</td><td>2.2.2A and flashing criteria have specific applicability; interaction motion2.3.3AAA is not an AA-only label</td></tr><tr><td>Forced colors</td><td>Use real OS/browser forced-color mode and inspect control boundaries/focus/meaning beyond shadows/color</td><td>Useful compatibility/usability check; do not label the media query itself a standalone WCAG pass</td></tr><tr><td>Targets/dragging</td><td>Measure targets and permitted spacing, operate nondrag alternatives and preserve moved-item focus/status</td><td>2.5.7AA /2.5.8AA; consult defined exceptions rather than universal pixel slogans</td></tr><tr><td>Authentication</td><td>Test paste/password manager, errors/session recovery and relevant cognitive alternatives</td><td>3.3.8AA and related input/error criteria; secure auth still needs server controls</td></tr></tbody></table><p>Qualifying large text for the contrast criterion is at least18pt regular or14pt bold (equivalent CSS sizing must be understood); do not simply call any h1 “large” or judge contrast by antialiasing screenshots. Inactive controls have criterion exceptions, but low-contrast explanatory text is not automatically inactive. Color-only status needs another visual/semantic cue. Focus styling needs contrast against the actual adjacent background, not a palette token tested in isolation.</p><p>For a wide data table, the table may require horizontal navigation, but search, pagination and row action controls should still reflow/operate. Fixed-height cards/dialogs often fail enlarged text even when font size uses rem. Test long/error/translated content rather than only a short happy-path screenshot. Prefer responsive layout/content fixes over hiding essential text or disabling enlargement.</p><p>Normative source checked2026-10-21: <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noreferrer">WCAG2.2</a>. Explanatory sources: <a href="https://www.w3.org/WAI/WCAG22/Understanding/resize-text.html" target="_blank" rel="noreferrer">resize text</a>, <a href="https://www.w3.org/WAI/WCAG22/Understanding/reflow.html" target="_blank" rel="noreferrer">reflow</a>, <a href="https://www.w3.org/WAI/WCAG22/Understanding/text-spacing.html" target="_blank" rel="noreferrer">text spacing</a>, <a href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noreferrer">contrast minimum</a>. These are study/test procedures, not a completed audit or readiness assessment.</p><h2 id="a-scoped-evidence-record-not-a-percentage-score" tabindex="-1">A scoped evidence record, not a percentage score <a class="header-anchor" href="#a-scoped-evidence-record-not-a-percentage-score" aria-label="Permalink to “A scoped evidence record, not a percentage score”">​</a></h2><p>For the <a href="./../Other/Cross_Browser_Progressive_Enhancement.html">worked HTML-first search</a>, a small component review can begin with the record below. It is a template with <strong>unperformed</strong> rows, not an audit result or a complete list of applicable criteria. Define the entire page/process, versions, input methods, states and accessibility-supported technology combinations before deciding whether a conformance claim is justified.</p><table tabindex="0"><thead><tr><th>Criterion / state</th><th>Procedure / expected outcome</th><th>Evidence and result</th></tr></thead><tbody><tr><td>1.3.1 / 4.1.2 input</td><td>Inspect label association and name/role in the actual accessibility tree; confirm reader identification</td><td>Unperformed; record environment/observation/trace</td></tr><tr><td>2.1.1 / 2.4.7 keyboard</td><td>Tab to input/button, submit with Enter, activate fallback; visible focus throughout</td><td>Unperformed; retain task steps and actual result</td></tr><tr><td>3.3.1 / 3.3.2 invalid query</td><td>Try missing/invalid data and bypass client validation; understandable identification and correction</td><td>Unperformed; retain client/server state and recovery</td></tr><tr><td>4.1.3 asynchronous results</td><td>Submit enhancement; verify appropriate announcement without forced focus movement</td><td>Unperformed; actual reader/browser evidence required</td></tr><tr><td>1.4.10 / 1.4.4 narrow/enlarged</td><td>Run specified reflow and text-resize checks; no clipped required action</td><td>Unperformed; measurements/screenshots plus task result</td></tr></tbody></table><p>Use pass/fail/not-applicable with a reason only after the procedure is executed; unknown/unperformed stays explicit. If a label is removed, first document the observed name/task failure, then restore it and retest the same combination. Do not fill a “pass” cell because source markup looks plausible. Capture defect impact, scope, fix and retest date separately from severity and criterion level. Other criteria, complete-process coverage, non-interference and accessibility-supported usage still need assessment. Native browser/reader/visual checks in this study environment remain unperformed.</p><h2 id="separate-practice" tabindex="-1">Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “Separate practice”">​</a></h2><p>Apply the <a href="./../../practice/frontend/a11y/What_is_WCAG_standard__What_parts_it_contains_Web_Content_Accessibility_Guidelines.html">focused requirements and failure cases</a>. All learner practice remains outstanding; the worked examples above are explanatory material.</p>',44)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
